action.command:
cd /workspace/app && grep -rn "minimumReleaseAge" /opt/node/lib/node_modules/pnpm/dist/pnpm.mjs | grep -iE "1440|2880|4320|720|default|DEFAULT|minutes|24 \* 60" | head; echo "=== search for a numeric literal default assignment ==="; cat > /tmp/scan8.mjs <<'EOF'
import fs from "fs";
const s = fs.readFileSync("/opt/node/lib/node_modules/pnpm/dist/pnpm.mjs","utf8");
const re=/minimumReleaseAge[^;\n]{0,60}=\s*(\d+)/g;
let m;
while((m=re.exec(s))){ console.log("assign:", m[0]); }
// also look for '1440' '2880' etc near 'age'
const re2=/(minimumReleaseAge|releaseAge)[^\n]{0,40}\b(1440|2880|4320|720|10080|43200)\b/g;
while((m=re2.exec(s))){ console.log("num:", m[0]); }
EOF
node /tmp/scan8.mjs

